SELECT sdi.id, sdi.category_id, sdc.name as category_name, sdc.code as category_code, sdi.item_code, sdi.item_name, sdi.description, sdi.sort_order, sdi.is_default, sdi.status, sdi.extend_data, sdi.created_at, creator.nickname as created_by_name, sdi.updated_at, updater.nickname as updated_by_name FROM sys_dict_item sdi INNER JOIN sys_dict_category sdc ON sdi.category_id = sdc.id AND sdc.delflag = 0 LEFT JOIN users creator ON sdi.created_by = creator.id LEFT JOIN users updater ON sdi.updated_by = updater.id WHERE sdi.delflag = 0
AND sdi.category_id = #{query.categoryId}
AND sdi.tenant_id = #{query.tenantId}
AND (sdi.item_code LIKE CONCAT('%', #{query.keyword}, '%') OR sdi.item_name LIKE CONCAT('%', #{query.keyword}, '%'))
AND sdi.status = #{query.status}
AND sdi.is_default = #{query.isDefault}
ORDER BY sdi.sort_order ASC, sdi.id ASC
LIMIT #{query.size} OFFSET #{query.offset}

SELECT COUNT(1)
FROM sys_dict_item sdi
INNER JOIN sys_dict_category sdc ON sdi.category_id = sdc.id AND sdc.delflag = 0
WHERE sdi.delflag = 0

    AND sdi.category_id = #{query.categoryId}


    AND sdi.tenant_id = #{query.tenantId}


