         OR sdi.item_name LIKE CONCAT('%', #{query.keyword}, '%'))


    AND sdi.status = #{query.status}


    AND sdi.is_default = #{query.isDefault}

SELECT sdi.id, sdi.category_id, sdc.name as category_name, sdc.code as category_code, sdi.item_code, sdi.item_name, sdi.description, sdi.sort_order, sdi.is_default, sdi.status, sdi.extend_data, sdi.created_at, creator.nickname as created_by_name, sdi.updated_at, updater.nickname as updated_by_name FROM sys_dict_item sdi INNER JOIN sys_dict_category sdc ON sdi.category_id = sdc.id AND sdc.delflag = 0 LEFT JOIN users creator ON sdi.created_by = creator.id LEFT JOIN users updater ON sdi.updated_by = updater.id WHERE sdi.category_id = #{categoryId} AND sdi.delflag = 0
AND sdi.tenant_id = #{tenantId}
AND sdi.status = #{status}
ORDER BY sdi.sort_order ASC, sdi.id ASC

SELECT sdi.id, sdi.category_id, sdc.name as category_name, sdc.code as category_code, sdi.item_code, sdi.item_name, sdi.description, sdi.sort_order, sdi.is_default, sdi.status, sdi.extend_data, sdi.created_at, creator.nickname as created_by_name, sdi.updated_at, updater.nickname as updated_by_name FROM sys_dict_item sdi INNER JOIN sys_dict_category sdc ON sdi.category_id = sdc.id AND sdc.delflag = 0 LEFT JOIN users creator ON sdi.created_by = creator.id LEFT JOIN users updater ON sdi.updated_by = updater.id WHERE sdc.code = #{categoryCode} AND sdi.delflag = 0
AND sdi.tenant_id = #{tenantId}
AND sdi.status = #{status}
ORDER BY sdi.sort_order ASC, sdi.item_name ASC

SELECT * FROM sys_dict_item
WHERE category_id = #{categoryId}
AND item_code = #{itemCode}
AND tenant_id = #{tenantId}
AND delflag = 0

    AND id != #{excludeId}

LIMIT 1

